// ═══════════════════════════════════════════════════════════════════
// VERTICAL FADER
// ═══════════════════════════════════════════════════════════════════

@Composable
private fun VerticalFader(
    value: Float,
    onValueChange: (Float) -> Unit,
    modifier: Modifier = Modifier,
    valueRange: ClosedFloatingPointRange<Float> = -60f..12f,
    onMidiLearn: (() -> Unit)? = null
) {
    val min = valueRange.start
    val max = valueRange.endInclusive
    val range = max - min

    Box(
        modifier = modifier
            .pointerInput(Unit) {
                detectTapGestures(
                    onTap = { offset ->
                        val fraction = 1f - (offset.y / size.height).coerceIn(0f, 1f)
                        onValueChange(min + fraction * range)
                    },
                    onLongPress = {
                        onMidiLearn?.invoke()
                    }
                )
            }
            .pointerInput(value, min, max, range) {
                detectDragGestures { change, dragAmount ->
                    val fractionDelta = -dragAmount.y / size.height
                    val newValue = (value + fractionDelta * range).coerceIn(min, max)
                    onValueChange(newValue)
                    change.consume()
                }
            }
    ) {
        val thumbHeight = 28.dp
        val fraction = ((value - min) / range).coerceIn(0f, 1f)

        Canvas(modifier = Modifier.fillMaxSize()) {
            val cx = size.width / 2f
            val trackW = 6.dp.toPx()
            val thumbH = thumbHeight.toPx()
            val halfThumb = thumbH / 2f
            val topY = halfThumb
            val bottomY = size.height - halfThumb

            // Track background
            drawLine(
                color = PanelHighlight.copy(alpha = 0.3f),
                start = Offset(cx, topY),
                end = Offset(cx, bottomY),
                strokeWidth = trackW,
                cap = StrokeCap.Round
            )

            // Active track
            val thumbY = bottomY - (bottomY - topY) * fraction
            drawLine(
                color = KnobAmber,
                start = Offset(cx, thumbY),
                end = Offset(cx, bottomY),
                strokeWidth = trackW,
                cap = StrokeCap.Round
            )

            // Thumb body
            val thumbW = 32.dp.toPx()
            val thumbLeft = cx - thumbW / 2f
            val thumbTop = thumbY - halfThumb
            drawRoundRect(
                color = BgPanel,
                topLeft = Offset(thumbLeft, thumbTop),
                size = Size(thumbW, thumbH),
                cornerRadius = CornerRadius(4.dp.toPx(), 4.dp.toPx())
            )
            drawRoundRect(
                color = KnobAmber,
                topLeft = Offset(thumbLeft, thumbTop),
                size = Size(thumbW, thumbH),
                cornerRadius = CornerRadius(4.dp.toPx(), 4.dp.toPx()),
                style = androidx.compose.ui.graphics.drawscope.Stroke(width = 2.dp.toPx())
            )

            // Thumb center line
            drawLine(
                color = TextSecondary,
                start = Offset(cx - 6.dp.toPx(), thumbY),
                end = Offset(cx + 6.dp.toPx(), thumbY),
                strokeWidth = 1.5f
            )
        }
    }
}

// ═══════════════════════════════════════════════════════════════════
// LEVEL METER
// ═══════════════════════════════════════════════════════════════════

@Composable
private fun LevelMeter(
    level: Float,
    modifier: Modifier = Modifier
) {
    Canvas(modifier = modifier.clip(RoundedCornerShape(4.dp))) {
        val w = size.width
        val h = size.height

        // Background
        drawRect(color = BgGunmetal)

        // Bar
        val barH = h * level.coerceIn(0f, 1f)
        val gradient = Brush.verticalGradient(
            colors = listOf(KnobGreen, KnobAmber, KnobRed),
            startY = h,
            endY = 0f
        )
        drawRect(
            brush = gradient,
            topLeft = Offset(0f, h - barH),
            size = Size(w, barH)
        )

        // LED segment dividers
        val segCount = 10
        val segH = h / segCount
        for (i in 1 until segCount) {
            val y = i * segH
            drawLine(
                color = BgPanel,
                start = Offset(0f, y),
                end = Offset(w, y),
                strokeWidth = 1.5f
            )
        }
    }
}

// ═══════════════════════════════════════════════════════════════════
// SMALL TOGGLE (M / S / R)
