data class ChannelState(
    val faderDb: Float = 0f,
    val pan: Float = 0f,
    val mute: Boolean = false,
    val solo: Boolean = false,
    val arm: Boolean = false,
    val level: Float = 0f,
    val sendA: Float = 0f,
    val sendB: Float = 0f,
    val inserts: List<InsertSlot> = List(4) { InsertSlot() }
)

