            inserts[slot] = InsertSlot()
            ch.copy(inserts = inserts)
        }
    }

    fun toggleInsertBypass(trackIndex: Int, slot: Int) {
        val current = _uiState.value.channels[trackIndex].inserts.getOrNull(slot) ?: return
        val newBypass = !current.bypass
